-- ═══════════════════════════════════════════════════════════════════
-- RAHTIS · румынский язык (16.11.2026)
--
-- Румынский стал языком платформы и приложения водителя
-- (src/lib/i18n: locales, DRIVER_LOCALES). Здесь то, что живёт в базе:
--   1. язык приложения водителя может быть 'ro';
--   2. вопросы тренажёра на румынском — 89 карточек, переведены с
--      английских (действующих) при засеве.
--
-- ВОПРОСЫ НЕ ПРОВЕРЕНЫ (reviewed_at пуст): водителю они не видны, пока
-- инструктор не отметит их в админке (/admin/training) — как при засеве
-- остальных языков 27.09.2026.
-- ═══════════════════════════════════════════════════════════════════

alter table public.drivers
  drop constraint drivers_app_language,
  add constraint drivers_app_language check (
    app_language is null
    or app_language in ('fi', 'en', 'et', 'ru', 'sv', 'lv', 'lt', 'pl', 'nb', 'da', 'ro')
  );

alter table public.training_questions
  drop constraint training_questions_locale,
  add constraint training_questions_locale check (
    locale in ('fi', 'en', 'et', 'ru', 'sv', 'lv', 'lt', 'pl', 'nb', 'da', 'ro')
  );

on conflict (card_key, locale) do nothing;
