insert into public.training_questions
  (module, card_key, locale, question, options, correct_index, explanation, hint, legal_ref, valid_from)
values
  ('adr', 'adr.a1', 'ro', 'Ce înseamnă numărul de sus de pe panoul portocaliu?', '["Numărul de identificare a pericolului","Masa mărfii","Numărul transportatorului","Codul de restricție pentru tuneluri"]'::jsonb, 0, 'Numărul de sus este numărul de identificare a pericolului, cel de jos este numărul ONU al substanței.', 'Numărul de jos identifică substanța.', 'ADR 5.3.2', null),
  ('adr', 'adr.a10', 'ro', 'Transportați butelii de gaz (clasa 2.1). Este necesar lichid pentru clătirea ochilor?', '["Da, întotdeauna","Nu — nu este obligatoriu pentru clasele 1 și 2","Doar pentru încărcături de peste 10 t","Doar la autocisterne"]'::jsonb, 1, 'Lichidul pentru clătirea ochilor nu este obligatoriu pentru mărfurile cu etichetele 1, 1.4, 1.5, 1.6, 2.1, 2.2 și 2.3. Restul echipamentului de bază este necesar.', 'Un gaz nu stropește în ochi ca un lichid.', 'ADR 8.1.5', null),
  ('adr', 'adr.a11', 'ro', 'Ce condiții trebuie să îndeplinească stingătorul la un transport ADR?', '["Doar să fie în cabină","Să aibă cel puțin 12 kg","Este suficient să fi fost cumpărat în ultimii cinci ani","Sigiliu și marcajul datei următoarei verificări, plus să fie ușor accesibil"]'::jsonb, 3, 'Stingătoarele trebuie să aibă sigiliu și marcajul datei următoarei verificări. Trebuie să fie ușor accesibile echipajului și protejate de intemperii.', 'Un stingător trebuie verificat periodic.', 'ADR 8.1.4', null),
  ('adr', 'adr.a12', 'ro', 'Ce echipament suplimentar este necesar pentru un lichid din clasa 3 (de ex. benzină)?', '["Lopată, dispozitiv de etanșare a canalizării și recipient colector","Mască de evacuare","Aparat de măsurare a radiațiilor","Nimic în plus"]'::jsonb, 0, 'Pentru solidele și lichidele cu etichetele 3, 4.1, 4.3, 8 și 9 sunt necesare o lopată, un dispozitiv de etanșare a canalizării și un recipient colector din plastic.', 'Gândiți-vă la o scurgere pe carosabil.', 'ADR 8.1.5.3', null),
  ('adr', 'adr.a2', 'ro', 'Ce înseamnă numărul de pericol 33?', '["Gaz toxic","Lichid coroziv","Lichid foarte inflamabil","Material radioactiv"]'::jsonb, 2, '3 înseamnă lichid inflamabil, iar o cifră dublată indică un pericol accentuat: lichid foarte inflamabil, cum este benzina.', 'O cifră dublată accentuează pericolul.', 'ADR 5.3.2.3', null),
  ('adr', 'adr.a3', 'ro', 'În fața numărului de pericol apare un X. Ce înseamnă?', '["Substanța este explozivă","Reacționează periculos cu apa — fără apă","Trebuie păstrată la rece","Tunelurile sunt interzise"]'::jsonb, 1, 'X înseamnă că substanța reacționează periculos cu apa. Apa poate fi folosită doar cu aprobarea specialiștilor.', 'Gândiți-vă la stingerea unui incendiu.', 'ADR 5.3.2.3', null),
  ('adr', 'adr.a4', 'ro', 'Ce document îi spune șoferului ce să facă în caz de accident și ce echipament este necesar?', '["Documentul de transport","Instrucțiunile scrise","Certificatul de înmatriculare","Certificatul ADR al șoferului"]'::jsonb, 1, 'Instrucțiunile scrise se păstrează în cabină, într-o limbă pe care șoferul o înțelege. Ele indică măsurile de luat și echipamentul necesar.', 'Se păstrează la îndemână, în cabină.', 'ADR 5.4.3', null),
  ('adr', 'adr.a5', 'ro', 'Cât timp este valabil certificatul ADR al șoferului?', '["1 an","3 ani","5 ani","Nelimitat"]'::jsonb, 2, 'Certificatul ADR al șoferului este valabil cinci ani. Se reînnoiește prin curs de reîmprospătare și examen.', 'La fel ca majoritatea calificărilor șoferilor.', 'ADR 8.2.2.8', null),
  ('adr', 'adr.a6', 'ro', 'Când trebuie făcut cursul de reîmprospătare ADR pentru ca noul certificat să continue direct pe cel vechi?', '["Oricând în perioada de valabilitate","În ultimul an înainte de expirare","Doar după expirare","La fiecare cinci ani, în ianuarie"]'::jsonb, 1, 'Dacă cursul de reîmprospătare și examenul sunt promovate în ultimul an înainte de expirare, noua perioadă de cinci ani începe de la data de expirare a celui vechi.', 'Dacă îl faceți prea devreme, valabilitatea se scurtează.', 'ADR 8.2.2.8.2', null),
  ('adr', 'adr.a7', 'ro', 'Aveți voie să fumați lângă vehicul în timpul încărcării la un transport ADR?', '["Da, dacă bate vântul în altă parte","Da, țigări electronice","Da, în cabină cu geamul închis","Nu — nici țigări electronice"]'::jsonb, 3, 'Fumatul este interzis în timpul manipulării, în apropierea vehiculului și în interiorul lui. Interdicția include și țigările electronice.', 'Interdicția se aplică tuturor dispozitivelor similare.', 'ADR 8.3.5', null),
  ('adr', 'adr.a8', 'ro', 'Poate funcționa motorul în timpul încărcării și descărcării?', '["Nu, decât dacă motorul este necesar pentru o pompă sau alt dispozitiv","Da, întotdeauna","Da, iarna","Doar la ralanti"]'::jsonb, 0, 'Motorul se oprește în timpul încărcării și descărcării, cu excepția cazului în care este necesar pentru acționarea pompelor sau a altor dispozitive ori legislația națională permite acest lucru.', 'Un motor pornit este o sursă de aprindere.', 'ADR 8.3.6', null),
  ('adr', 'adr.a9', 'ro', 'Ce înseamnă „cantitățile mici” din ADR 1.1.3.6 (1000 de puncte)?', '["Transportul este complet scutit de ADR","Cantitatea este limitată la 1000 kg","Sub limita pe unitate de transport, unele cerințe nu se aplică","Șoferul primește o reducere de 1000 de puncte"]'::jsonb, 2, 'În cazul scutirii pentru cantități mici nu sunt obligatorii, de exemplu, panourile portocalii și certificatul ADR al șoferului. Unele cerințe, cum ar fi un stingător de 2 kg și documentele, se aplică în continuare.', 'Scutirea este parțială.', 'ADR 1.1.3.6', null),
  ('cargo', 'cargo.g1', 'ro', 'Pentru ce forță de inerție se calculează asigurarea încărcăturii spre înainte (la frânare)?', '["0,3 din greutatea încărcăturii","0,5 din greutatea încărcăturii","0,8 din greutatea încărcăturii","1,0 din greutatea încărcăturii"]'::jsonb, 2, 'În transportul rutier, asigurarea spre înainte se calculează pentru 0,8 g — adică 80% din greutatea încărcăturii.', 'Spre înainte acționează cea mai mare forță dintre toate direcțiile.', 'EN 12195-1', null),
  ('cargo', 'cargo.g10', 'ro', 'Prelatele laterale ale unei semiremorci cu prelată culisantă rețin încărcătura?', '["Da, întotdeauna","De regulă nu — doar dacă suprastructura este certificată pentru asta și încărcătura este așezată conform certificatului","Da, dacă sunt bine întinse","Da, pentru încărcături de până la 10 t"]'::jsonb, 1, 'Prelatele obișnuite protejează de intemperii, nu asigură încărcătura. Pot fi luate în calcul doar dacă suprastructura este certificată (EN 12642, clasa XL) și încărcătura este așezată conform certificatului.', 'Prelata nu este perete lateral.', 'EN 12642', null),
  ('cargo', 'cargo.g11', 'ro', 'De ce este mai bine să blocați încărcătura spre înainte în peretele frontal decât să o rețineți cu chingi peste ea?', '["Este mai rapid","Împotriva a 0,8 g ar fi nevoie de foarte multe chingi peste încărcătură","Chingile peste încărcătură nu rețin deloc","Așa cere clientul"]'::jsonb, 1, 'O chingă peste încărcătură reține doar prin frecare. Împotriva a 0,8 g spre înainte ar fi nevoie de foarte multe. Blocarea în peretele frontal preia direct această forță, în limita rezistenței peretelui.', 'Comparați forțele spre înainte și lateral.', 'EN 12195-1', null),
  ('cargo', 'cargo.g12', 'ro', 'A încărcat depozitul, șoferul nu a participat. Cine răspunde de asigurarea încărcăturii pe drum?', '["Doar depozitul","Doar clientul","Și șoferul trebuie să verifice asigurarea înainte de plecare","Nimeni, dacă există CMR"]'::jsonb, 2, 'Șoferul răspunde de siguranța vehiculului și a încărcăturii pe drum. Chiar dacă au încărcat alții, șoferul trebuie să verifice asigurarea înainte de plecare și pe parcurs.', 'La un control în trafic, pe șofer îl întreabă.', 'Tieliikennelaki 729/2018', null),
  ('cargo', 'cargo.g13', 'ro', 'O chingă are STF 400 daN. Asta înseamnă aproximativ…', '["40 kg forță","400 kg forță","4.000 kg forță","40.000 kg forță"]'::jsonb, 1, '1 daN (decanewton) ≈ 1 kg forță. STF 400 daN înseamnă aproximativ 400 kg de tensiune.', 'Un daN este aproape un kilogram.', 'SI', null),
  ('cargo', 'cargo.g14', 'ro', 'Cum se așază încărcătura grea și cea ușoară?', '["Cele grele deasupra, ca să apese","Cele grele jos și la mijloc, ținând cont de sarcinile pe axe","Cum e cel mai ușor de încărcat","Cele grele în partea din spate a semiremorcii"]'::jsonb, 1, 'Mărfurile grele se pun jos și aproape de axa longitudinală, ca centrul de greutate să fie jos și sarcinile pe axe să rămână în limite.', 'Centru de greutate jos — stabilitate.', 'EU Best Practice Guidelines on Cargo Securing', null),
  ('cargo', 'cargo.g2', 'ro', 'Și pentru ce forță se calculează asigurarea laterală și spre înapoi?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Lateral și spre înapoi — 0,5 g, adică jumătate din greutatea încărcăturii.', 'Jumătate.', 'EN 12195-1', null),
  ('cargo', 'cargo.g3', 'ro', 'Ce înseamnă STF pe eticheta unei chingi de ancorare?', '["Sarcina maximă de rupere","Forța de tensionare pe care o dă clichetul cu forța normală a mâinii","Lungimea chingii","Anul de fabricație"]'::jsonb, 1, 'STF (Standard Tension Force) este forța de tensionare a clichetului, în daN. Contează la ancorarea prin apăsare (chinga trece peste încărcătură).', 'T vine de la tension (tensionare).', 'EN 12195-2', null),
  ('cargo', 'cargo.g4', 'ro', 'Ce înseamnă LC pe eticheta unei chingi de ancorare?', '["Sarcina admisă pe chingă la ancorarea directă","Forța de tensionare a clichetului","Coeficientul de frecare","Clasa încărcăturii"]'::jsonb, 0, 'LC (Lashing Capacity) este forța maximă pe care o suportă chinga la ancorarea directă (chinga merge de la încărcătură la punctul de ancorare).', 'Capacitate — sarcina admisă.', 'EN 12195-2', null),
  ('cargo', 'cargo.g5', 'ro', 'O chingă peste încărcătură este tensionată la 30° în loc de aproape 90°. Ce se întâmplă cu apăsarea în jos?', '["Aproape nu se schimbă","Scade cam la jumătate","Crește","Scade cu 10%"]'::jsonb, 1, 'Apăsarea este proporțională cu sinusul unghiului: sin 90° = 1, sin 30° = 0,5. O chingă cu unghi mic apasă de două ori mai slab — aveți nevoie de două ori mai multe chingi.', 'Cu cât chinga e mai abruptă, cu atât apasă mai tare.', 'EN 12195-1', null),
  ('cargo', 'cargo.g6', 'ro', 'De ce se pune un covoraș antiderapant sub încărcătură?', '["Ca să nu se zgârie podeaua","Mărește frecarea, deci sunt necesare mai puține chingi","Înlocuiește complet chingile","Ca să amortizeze încărcătura la încărcare"]'::jsonb, 1, 'Covorașul mărește coeficientul de frecare (de exemplu de la 0,45 la 0,6). Frecarea preia o parte din forță, iar sarcina pe chingi scade.', 'Cauciucul aderă mai bine decât lemnul.', 'EN 12195-1, Annex B', null),
  ('cargo', 'cargo.g7', 'ro', 'Între încărcătură și peretele frontal sunt 50 cm liberi. De ce este rău?', '["Nu este rău, dacă sunt chingi","La frânare încărcătura prinde viteză și lovește peretele frontal, iar blocarea nu funcționează","Doar pentru că încărcătura se poate zgâria","Influențează doar distribuția sarcinii pe axe"]'::jsonb, 1, 'Încărcătura cu spațiu liber apucă să se miște la frânare și lovește peretele frontal cu o forță mai mare. Spațiul trebuie eliminat sau umplut: cu paleți goi, perne de aer sau proptele.', 'Un impact e mai puternic decât o apăsare constantă.', 'EU Best Practice Guidelines on Cargo Securing', null),
  ('cargo', 'cargo.g8', 'ro', 'Eticheta unei chingi s-a rupt, dar chinga arată bine. O puteți folosi?', '["Da, dacă nu are tăieturi","Da, dacă o tensionați mai tare","Nu, o chingă fără etichetă nu se folosește","Doar pentru încărcături ușoare"]'::jsonb, 2, 'O chingă fără etichetă se scoate din uz: LC și STF ale ei sunt necunoscute. La fel și chingile tăiate sau cu clichet deteriorat.', 'Fără marcaj nu știți ce poate ține chinga.', 'EN 12195-2', null),
  ('cargo', 'cargo.g9', 'ro', 'La ce folosesc protecțiile de colț puse sub chingă?', '["Pentru aspect","Protejează chinga de muchiile ascuțite și distribuie tensiunea","Ca să nu alunece chinga pe prelată","Se folosesc doar la ADR"]'::jsonb, 1, 'Protecțiile de colț feresc chinga de tăieturi și ajută ca tensiunea să se distribuie peste încărcătură, nu să rămână pe o singură parte.', 'O muchie ascuțită taie chinga.', 'EU Best Practice Guidelines on Cargo Securing', null),
  ('ensiapu', 'ensiapu.e1', 'ro', 'Care este numărul de urgență în Finlanda și în restul UE?', '["911","112","110","118"]'::jsonb, 1, '112 funcționează în toată UE, chiar și fără cartelă SIM. Spuneți ce s-a întâmplat și unde, apoi răspundeți la întrebări.', 'Același număr peste tot în UE.', 'Käypä hoito: Elvytys / ERC', null),
  ('ensiapu', 'ensiapu.e2', 'ro', 'Un adult este inconștient și nu respiră normal. Ce faceți?', '["Îl puneți în poziție laterală de siguranță","Așteptați să își revină","Sunați la 112 și începeți resuscitarea 30:2","Îi dați ceva de băut"]'::jsonb, 2, 'Dacă un adult nu își revine și nu respiră normal, cereți ajutor și începeți imediat resuscitarea: 30 de compresii și 2 ventilații.', 'Timpul este decisiv.', 'Käypä hoito: Elvytys / ERC', null),
  ('ensiapu', 'ensiapu.e3', 'ro', 'În ce ritm faceți compresiile toracice?', '["60–80 pe minut","100–120 pe minut","140–160 pe minut","Cât de repede puteți"]'::jsonb, 1, 'Ritmul este de 100–120 de compresii pe minut, lăsând pieptul să revină între ele.', 'Cam două compresii pe secundă.', 'Käypä hoito: Elvytys / ERC', null),
  ('ensiapu', 'ensiapu.e4', 'ro', 'Cât de adânc comprimați pieptul unui adult la resuscitare?', '["1–2 cm","3–4 cm","5–6 cm","8–10 cm"]'::jsonb, 2, 'La un adult, pieptul se comprimă 5–6 cm, pe mijlocul sternului.', 'Mai adânc decât cred mulți.', 'Käypä hoito: Elvytys / ERC', null),
  ('ensiapu', 'ensiapu.e5', 'ro', 'Un rănit este inconștient, dar respiră normal. Ce faceți?', '["Îl puneți în poziție laterală de siguranță și urmăriți respirația","Începeți compresiile toracice","Îl ridicați în șezut","Îl lăsați pe spate și mergeți după ajutor"]'::jsonb, 0, 'Poziția laterală de siguranță menține căile respiratorii libere. Urmăriți în continuare respirația și începeți resuscitarea dacă se oprește.', 'Căile respiratorii trebuie să rămână libere.', 'Käypä hoito: Elvytys / ERC', null),
  ('ensiapu', 'ensiapu.e6', 'ro', 'Un braț sângerează abundent. Care este prima măsură?', '["Îi dați să bea","Spălați rana cu apă","Așteptați ambulanța fără să atingeți","Apăsați direct pe rană și ridicați membrul"]'::jsonb, 3, 'O sângerare abundentă se oprește prin apăsare directă pe rană. Ridicați membrul și aplicați un pansament compresiv. Cereți ajutor.', 'Apăsarea oprește sângerarea.', 'Käypä hoito: Elvytys / ERC', null),
  ('ensiapu', 'ensiapu.e7', 'ro', 'Un coleg și-a ars mâna de o țeavă de eșapament fierbinte. Ce faceți mai întâi?', '["Ungeți cu unt sau grăsime","Răciți cu apă rece aproximativ 20 de minute","Spargeți bășicile","Puneți gheață direct pe piele"]'::jsonb, 1, 'Arsura se răcește imediat cu apă rece timp de aproximativ 20 de minute. Fără grăsimi sau gheață, iar bășicile nu se sparg.', 'Apa preia căldura.', 'Käypä hoito: Elvytys / ERC', null),
  ('ensiapu', 'ensiapu.e8', 'ro', 'În timpul resuscitării se aduce un defibrilator (DEA). Ce faceți?', '["Îl porniți și urmați instrucțiunile, continuând compresiile","Opriți compresiile până vine ambulanța","Nu îl atingeți fără instruire","Îl folosiți doar dacă pacientul respiră"]'::jsonb, 0, 'Defibrilatorul vă ghidează vocal. Aplicați electrozii, urmați instrucțiunile și întrerupeți compresiile cât mai puțin.', 'Aparatul vă ghidează singur.', 'Käypä hoito: Elvytys / ERC', null),
  ('masses', 'masses.m1', 'ro', 'Care este masa maximă admisă pe o axă motoare în Finlanda?', '["10 t","11,5 t","13 t","9 t"]'::jsonb, 1, 'O axă motoare poate avea până la 11,5 t, o axă nemotoare 10 t.', 'Axa motoare poate duce mai mult decât una nemotoare.', 'VNa 1257/1992', null),
  ('masses', 'masses.m10', 'ro', 'De ce este periculoasă supraîncărcarea, chiar dacă camionul încă o trage?', '["Doar consumă mai mult combustibil","Este periculoasă doar din cauza amenzii","Crește distanța de frânare, iar anvelopele și frânele sunt suprasolicitate","Nu este periculoasă sub 10%"]'::jsonb, 2, 'Masa suplimentară mărește distanța de frânare, supraîncălzește frânele și suprasolicită anvelopele. Drumurile și podurile se uzează mai repede.', 'Gândiți-vă la frânarea în pantă.', 'VNa 1257/1992', null),
  ('masses', 'masses.m2', 'ro', 'Care este masa maximă admisă pe o axă simplă nemotoare?', '["8 t","10 t","11,5 t","12 t"]'::jsonb, 1, 'O axă simplă nemotoare poate avea până la 10 t.', 'Mai puțin decât o axă motoare.', 'VNa 1257/1992', null),
  ('masses', 'masses.m3', 'ro', 'Care este masa maximă admisă a unui ansamblu cu 5 axe?', '["40 t","42 t","44 t","48 t"]'::jsonb, 2, 'Un ansamblu cu cinci axe poate avea până la 44 t.', 'Peste 40, sub 48.', 'VNa 1257/1992', null),
  ('masses', 'masses.m4', 'ro', 'Care este masa maximă admisă a unui ansamblu cu 9 axe în Finlanda?', '["60 t","68 t","76 t","84 t"]'::jsonb, 2, 'În Finlanda, un ansamblu cu nouă axe poate avea până la 76 t, dacă distanțele dintre axe și construcția lui îndeplinesc cerințele.', 'Cea mai mare limită generală din Europa.', 'VNa 1257/1992', null),
  ('masses', 'masses.m5', 'ro', 'Care este lungimea maximă admisă a unui ansamblu în Finlanda?', '["18,75 m","25,25 m","34,5 m","40 m"]'::jsonb, 2, 'Lungimea maximă admisă a unui ansamblu este de 34,5 m.', 'Finlanda permite ansambluri lungi HCT.', 'VNa 1257/1992', null),
  ('masses', 'masses.m6', 'ro', 'Care este înălțimea maximă admisă a unui vehicul în Finlanda?', '["4,0 m","4,2 m","4,4 m","4,6 m"]'::jsonb, 2, 'Înălțimea maximă admisă este de 4,4 m. La poduri și pasaje subterane verificați oricum gabaritul indicat de indicatoare.', 'Mai mult decât în multe alte țări din UE.', 'VNa 1257/1992', null),
  ('masses', 'masses.m7', 'ro', 'La un punct de descărcare s-a descărcat partea din spate a unei semiremorci pline. Masa totală a scăzut. Ce se poate întâmpla?', '["Nimic, masa a scăzut","Axa motoare poate fi supraîncărcată","Boghiul semiremorcii este supraîncărcat","Axa de direcție se ridică"]'::jsonb, 1, 'Încărcătura rămasă este acum mai aproape de șa, așa că o parte mai mare din ea revine capului tractor, în special axei motoare.', 'Gândiți-vă unde s-a mutat centrul de greutate al încărcăturii.', 'VNa 1257/1992', null),
  ('masses', 'masses.m8', 'ro', 'Încărcătura a fost declarată de expeditor. La control, camionul este supraîncărcat. Cine răspunde?', '["Doar expeditorul","Doar transportatorul","Și șoferul","Nimeni, dacă greutatea e trecută în CMR"]'::jsonb, 2, 'Șoferul răspunde de încărcarea vehiculului pe drum. Sancțiunile îi pot viza și pe transportator și pe expeditor.', 'La control, șoferul este întrebat primul.', 'Tieliikennelaki 729/2018', null),
  ('masses', 'masses.m9', 'ro', 'Masa maximă înmatriculată este mai mică decât limita legală. Pe care o respectați?', '["Limita legală","Masa înmatriculată, cea mai mică","Cea mai mare","Media lor"]'::jsonb, 1, 'Se aplică întotdeauna limita cea mai mică: cea legală, masa înmatriculată sau restricția de tonaj a drumului.', 'Un vehicul nu poate duce mai mult decât este omologat.', 'VNa 1257/1992', null),
  ('tacho', 'tacho.b1', 'ro', 'Ați condus 4 h 30 min fără pauză. Ce urmează?', '["Pauză de 30 min","Pauză de 45 min","Pauză de 15 min","Puteți conduce până la 5 h"]'::jsonb, 1, 'După 4 h 30 min de conducere, luați o pauză de cel puțin 45 min, dacă nu ați împărțit-o mai devreme.', 'Este cea mai cunoscută regulă de tahograf.', '561/2006, art. 7', null),
  ('tacho', 'tacho.b2', 'ro', 'Pauza de 45 de minute se poate împărți în 30 + 15 minute?', '["Da, în orice ordine","Nu, doar 15 și apoi 30","Da, dar doar pe feribot","Nu, nu se poate împărți deloc"]'::jsonb, 1, 'Pauza se poate împărți doar astfel: întâi cel puțin 15 min, apoi cel puțin 30 min. Ordinea 30 + 15 nu este valabilă.', 'Ordinea contează.', '561/2006, art. 7', null),
  ('tacho', 'tacho.b3', 'ro', 'Încărcarea a durat 45 de minute. Se socotește ca pauză?', '["Da, dacă nu ați stat la volan","Da, dacă camionul a stat pe loc","Nu, este „altă muncă”","Doar dacă altcineva a făcut încărcarea"]'::jsonb, 2, 'Încărcarea, descărcarea și verificările vehiculului sunt „altă muncă” (simbolul cu ciocane încrucișate). Pauza înseamnă doar odihnă.', 'Pauza este timpul în care nu prestați nicio muncă.', '561/2006, art. 4; 2002/15/EC', null),
  ('tacho', 'tacho.c1', 'ro', 'Control în trafic. Pentru ce perioadă trebuie să prezentați înregistrările?', '["Ziua în curs și cele 28 anterioare","Ziua în curs și cele 56 anterioare","Doar săptămâna în curs","Ultimele 90 de zile"]'::jsonb, 1, 'Din 31.12.2024 șoferul trebuie să prezinte înregistrările pentru ziua în curs și cele 56 de zile anterioare.', 'Înainte erau 28 — acum e dublu.', '165/2014, art. 36 (2020/1054)', null),
  ('tacho', 'tacho.c2', 'ro', 'Cât de des trebuie descărcate datele de pe cardul de conducător auto?', '["La fiecare 7 zile","La fiecare 28 de zile","La fiecare 90 de zile","O dată pe an"]'::jsonb, 1, 'Datele de pe cardul de conducător auto se descarcă cel puțin o dată la 28 de zile. Datele din unitatea de bord, cel puțin o dată la 90 de zile.', 'Perioada pentru card este mai scurtă decât pentru unitatea de bord.', '(EU) 581/2010', null),
  ('tacho', 'tacho.c3', 'ro', 'Cardul de conducător auto s-a defectat în timpul cursei. Ce este corect?', '["Opresc imediat lucrul","Conduc fără înregistrări și le notez mai târziu","Raportez și solicit înlocuirea în 7 zile; cel mult 15 zile conduc cu imprimate la începutul și la sfârșitul turei","Folosesc cardul unui coleg"]'::jsonb, 2, 'Un card defect sau pierdut se raportează autorităților și se solicită înlocuirea în 7 zile calendaristice. Puteți conduce fără card cel mult 15 zile, făcând și semnând imprimate la începutul și la sfârșitul fiecărei ture.', 'Nu folosiți niciodată cardul altcuiva.', '165/2014, art. 29, 35', null),
  ('tacho', 'tacho.c4', 'ro', 'Ați trecut o frontieră. Ce faceți cu tahograful (dacă nu înregistrează singur)?', '["Nimic","Introduceți simbolul țării la prima oprire posibilă după frontieră","Introduceți țara doar la sfârșitul turei","Faceți un imprimat"]'::jsonb, 1, 'Simbolul țării se introduce la primul loc de oprire posibil după trecerea frontierei. Tahografele inteligente de generația a doua fac acest lucru automat.', 'Nu în timpul mersului — la prima oprire.', '165/2014, art. 34(7)', null),
  ('tacho', 'tacho.c5', 'ro', 'Ce înseamnă simbolul cu ciocane încrucișate?', '["Conducere","Altă muncă","Disponibilitate","Repaus"]'::jsonb, 1, 'Ciocane — altă muncă. Volan — conducere. Pătrat cu diagonală — disponibilitate. Pat — repaus și pauză.', 'Ciocanul este o unealtă de lucru.', '165/2014, Annex IC', null),
  ('tacho', 'tacho.d1', 'ro', 'Care este timpul maxim de conducere zilnic pentru un camion?', '["8 h","9 h, până la 10 h de cel mult două ori pe săptămână","10 h în fiecare zi","11 h"]'::jsonb, 1, 'Timpul de conducere zilnic este de 9 h. Poate fi prelungit la 10 h de două ori pe săptămână.', 'Căutați răspunsul care conține și limita de bază, și excepția.', '561/2006, art. 6(1)', null),
  ('tacho', 'tacho.d2', 'ro', 'Care este limita de conducere pentru o săptămână?', '["48 h","56 h","60 h","90 h"]'::jsonb, 1, 'Cel mult 56 h de conducere pe săptămână.', 'Este mai puțin decât 9 h × 6 zile.', '561/2006, art. 6(2)', null),
  ('tacho', 'tacho.d3', 'ro', 'Cât puteți conduce în total în două săptămâni consecutive?', '["90 h","100 h","112 h","120 h"]'::jsonb, 0, 'Cel mult 90 h în oricare două săptămâni consecutive. Deci două săptămâni la rând de câte 56 h nu sunt posibile.', 'Nu puteți conduce două săptămâni maxime la rând.', '561/2006, art. 6(3)', null),
  ('tacho', 'tacho.r1', 'ro', 'Cât durează repausul zilnic normal?', '["9 h","10 h","11 h, se poate împărți 3 + 9","12 h fără împărțire"]'::jsonb, 2, 'Repausul zilnic normal este de 11 h. Poate fi împărțit: întâi cel puțin 3 h, apoi cel puțin 9 h (12 h în total).', 'Împărțirea face totalul mai lung.', '561/2006, art. 4(g), 8', null),
  ('tacho', 'tacho.r2', 'ro', 'Cât de des puteți lua un repaus zilnic redus de 9 ore?', '["În fiecare zi","De cel mult 3 ori între două repausuri săptămânale","De cel mult două ori pe săptămână","Doar la cursele internaționale"]'::jsonb, 1, 'Repausul zilnic redus (între 9 și 11 h) poate fi luat de cel mult trei ori între două perioade de repaus săptămânal.', 'Este același număr ca la prelungirile timpului de conducere? Nu, e mai mare.', '561/2006, art. 8(4)', null),
  ('tacho', 'tacho.w1', 'ro', 'Puteți petrece repausul săptămânal normal (45 h) în cabină?', '["Da, dacă există cușetă","Da, într-o parcare securizată","Nu, este necesară o cazare adecvată","Da, dacă șoferul este de acord"]'::jsonb, 2, 'Repausul săptămânal normal și orice repaus săptămânal de peste 45 h luat drept compensare nu pot fi petrecute în cabină. Angajatorul organizează și plătește cazarea.', 'Este una dintre schimbările principale ale Pachetului Mobilitate.', '561/2006, art. 8(8a)', null),
  ('tacho', 'tacho.w2', 'ro', 'Repausul săptămânal redus minim este de…', '["9 h","24 h","36 h","45 h"]'::jsonb, 1, 'Repausul săptămânal redus este de cel puțin 24 h. Diferența trebuie compensată într-o singură tranșă, până la sfârșitul celei de-a treia săptămâni care urmează.', 'Exact o zi.', '561/2006, art. 8(6)', null),
  ('tacho', 'tacho.w3', 'ro', 'Când trebuie să înceapă repausul săptămânal?', '["După 56 h de conducere","Cel târziu după 6 perioade de 24 h de la cel anterior","Duminica","La 7 zile după începerea lucrului"]'::jsonb, 1, 'Repausul săptămânal începe cel târziu la sfârșitul a șase perioade de 24 de ore de la încheierea repausului săptămânal anterior.', 'Șase zile de muncă este maximul.', '561/2006, art. 8(6)', null),
  ('tacho', 'tacho.w4', 'ro', 'Cât de des trebuie să se poată întoarce acasă sau la bază un șofer pe curse internaționale?', '["La fiecare 2 săptămâni","La fiecare 4 săptămâni","La fiecare 6 săptămâni","O dată pe trimestru"]'::jsonb, 1, 'Angajatorul organizează întoarcerea șoferului la centrul operațional sau la domiciliu în fiecare perioadă de 4 săptămâni consecutive.', 'Cam o dată pe lună.', '561/2006, art. 8(8a)', null),
  ('tacho', 'tacho.x1', 'ro', 'Mai aveți 1,5 h până acasă pentru repausul săptămânal, dar timpul de conducere s-a epuizat. Ce este permis?', '["Nimic, trebuie să opriți","Continuați dacă ați luat o pauză de 30 min chiar înainte și notați manual motivul","Continuați fără condiții","Sunați dispecerul, care vă permite"]'::jsonb, 1, 'În cazuri excepționale puteți depăși limita cu cel mult 1 h sau cu cel mult 2 h, dacă ați luat imediat înainte o pauză neîntreruptă de 30 min, pentru a ajunge acasă sau la bază pentru repausul săptămânal normal. Motivul trebuie notat manual, iar depășirea compensată.', 'Există o excepție, dar cu condiții și documentare.', '561/2006, art. 12', null),
  ('tacho', 'tacho.x2', 'ro', 'Repausul zilnic pe feribot: de câte ori poate fi întrerupt?', '["Nu poate fi întrerupt","De cel mult două ori, în total cel mult 1 h, cu acces la cușetă","De câte ori doriți","O dată, pentru cel mult 2 h"]'::jsonb, 1, 'Repausul pe feribot sau tren poate fi întrerupt de cel mult două ori, în total cel mult o oră. Șoferul trebuie să aibă acces la o cușetă.', 'De două ori, o oră.', '561/2006, art. 9', null),
  ('tech', 'tech.t1', 'ro', 'Când se face verificarea înainte de plecare?', '["O dată pe săptămână","Înainte de plecare, în fiecare zi, și după fiecare cuplare","Doar la inspecția tehnică anuală","Doar dacă se aprinde un martor de avertizare"]'::jsonb, 1, 'Șoferul trebuie să se asigure, înainte de a conduce, că vehiculul este în stare tehnică bună. Verificarea zilnică se face înainte de plecare și la fiecare cuplare a unei remorci.', 'Inspecția tehnică anuală nu este suficientă pentru condusul zilnic.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t10', 'ro', 'Cine răspunde de starea tehnică a vehiculului când conduceți?', '["Doar service-ul","Șoferul, dar și proprietarul sau deținătorul","Doar stația ITP","Doar angajatorul"]'::jsonb, 1, 'Șoferul nu are voie să plece cu un vehicul despre care știe sau ar trebui să știe că este defect. Răspund și proprietarul și deținătorul.', 'La volan stă o singură persoană.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t2', 'ro', 'Un indicator de piuliță de roată arată în altă direcție decât celelalte. Ce înseamnă?', '["Indicatorul este doar decorativ","Piulița este prea strânsă","Piulița s-ar putea să se fi slăbit","Anvelopa trebuie înlocuită"]'::jsonb, 2, 'Indicatoarele sunt montate în linie. Dacă unul s-a rotit, piulița s-ar putea să se fi slăbit. Verificați cuplul de strângere înainte de plecare.', 'Indicatorul se rotește odată cu piulița.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t3', 'ro', 'Din jurul unei piulițe de roată pornește o dâră maronie. Ce vă indică?', '["Vopseaua jantei s-a uzat","Piulița poate fi slăbită","Frânele sunt fierbinți","Nimic, este normal"]'::jsonb, 1, 'O dâră de rugină în jurul piuliței apare când piulița se mișcă. Strângeți și verificați roata înainte de plecare.', 'Mișcarea produce uzură și rugină.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t4', 'ro', 'După oprirea motorului auziți un șuierat continuu la semiremorcă. Ce faceți?', '["Găsiți scurgerea înainte de plecare","Plecați, presiunea va ajunge","Măriți turația motorului","Raportați la sfârșitul săptămânii"]'::jsonb, 0, 'Șuieratul înseamnă o pierdere de aer. O scurgere de aer la frâne poate face ca frânele semiremorcii să nu mai funcționeze. Defecțiunea se găsește înainte de plecare.', 'Frânele funcționează cu aer comprimat.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t5', 'ro', 'Ați cuplat o semiremorcă. Ce verificați înainte de plecare?', '["Doar luminile","Doar numărul de înmatriculare","Închiderea, siguranța, conexiunile și o probă de tracțiune cu frânele semiremorcii acționate","Nimic, dacă cuplarea a sunat bine"]'::jsonb, 2, 'După cuplare verificați închiderea șei și siguranța, conexiunile de aer și electrice, picioarele de sprijin și faceți o probă de tracțiune cu frânele semiremorcii acționate.', 'Un zgomot nu dovedește că șaua s-a închis.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t6', 'ro', 'Pe flancul anvelopei este o umflătură. Ce faceți?', '["Conduceți cu grijă până la destinație","Umflați mai tare","Conduceți până se dezumflă anvelopa","Înlocuiți anvelopa înainte de plecare"]'::jsonb, 3, 'O umflătură înseamnă carcasă deteriorată. Anvelopa poate exploda în mers, deci nu plecați cu ea.', 'O umflătură nu se repară singură.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t7', 'ro', 'În timpul mersului se aprinde martorul de presiune în sistemul de frânare. Ce faceți?', '["Continuați dacă frânele par în regulă","Opriți într-un loc sigur și nu continuați până nu găsiți defecțiunea","Conduceți mai repede, ca să țină pasul compresorul","Stingeți martorul de avertizare"]'::jsonb, 1, 'Presiunea scăzută în sistemul de frânare poate slăbi frânele sau bloca frânele cu arc. Opriți în siguranță și găsiți defecțiunea.', 'Martorul este ultimul avertisment înainte de cedare.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t8', 'ro', 'Care este adâncimea minimă a profilului unei anvelope de vară?', '["1,0 mm","1,6 mm","3,0 mm","5,0 mm"]'::jsonb, 1, 'O anvelopă de vară trebuie să aibă cel puțin 1,6 mm adâncime a profilului. Anvelopele de iarnă au cerințe proprii, mai mari.', 'Aceeași limită ca la autoturisme vara.', 'Tieliikennelaki 729/2018', null),
  ('tech', 'tech.t9', 'ro', 'Seara observați că o lampă spate a semiremorcii nu funcționează. Ce faceți?', '["Continuați, celelalte lumini funcționează","Porniți avariile pentru toată cursa","Reparați sau înlocuiți lampa înainte să continuați pe întuneric","Anunțați service-ul săptămâna viitoare"]'::jsonb, 2, 'Un vehicul nu poate fi folosit cu lumini defecte. Pe întuneric, cei din spate nu vă vor vedea la timp.', 'Gândiți-vă la șoferul din spate pe un drum întunecat.', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r1', 'ro', 'Camionul se defectează pe un drum principal. Ce faceți mai întâi?', '["Coborâți imediat să vedeți defecțiunea","Porniți avariile și, dacă se poate, mutați vehiculul într-un loc sigur, în afara benzii","Sunați angajatorul cât stați pe bandă","Puneți triunghiul înainte de a opri"]'::jsonb, 1, 'Mai întâi avertizați ceilalți participanți la trafic și ieșiți de pe banda de circulație. Abia apoi coborâți, purtând vestă reflectorizantă.', 'Întâi ceilalți participanți la trafic, apoi defecțiunea.', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r2', 'ro', 'Când puneți vesta reflectorizantă dacă opriți pe marginea drumului?', '["După ce ați pus triunghiul","Doar pe întuneric","Înainte de a coborî din cabină","Doar pe autostradă"]'::jsonb, 2, 'Puneți vesta reflectorizantă încă din cabină, ca să fiți vizibil din momentul în care coborâți pe carosabil.', 'Întâi vizibilitatea, apoi coborâți.', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r3', 'ro', 'Unde puneți triunghiul reflectorizant?', '["Suficient de departe în spatele vehiculului ca cei care vin să poată reacționa; mai departe dacă traficul e rapid","Lângă vehicul","În fața vehiculului","Oriunde, numai să se vadă"]'::jsonb, 0, 'Triunghiul se pune suficient de departe în spate pentru ca cei care vin să observe pericolul și să încetinească. Cu cât viteza e mai mare și vizibilitatea mai slabă, cu atât mai departe.', 'Cei care se apropie au nevoie de timp să frâneze.', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r4', 'ro', 'Camionul a oprit pe banda de urgență a autostrăzii. Unde este cel mai sigur să aștepte oamenii?', '["În cabină, cu centurile puse","În fața camionului, pe acostament","În spatele camionului, ca să fiți văzut","După parapet, lateral față de vehicul"]'::jsonb, 3, 'Pe autostradă vehiculul poate fi lovit din spate. Cel mai sigur este să așteptați după parapet, lateral față de vehicul, nu în fața sau în spatele lui.', 'Unde ar lovi o mașină venită din spate?', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r5', 'ro', 'La lucrări pe drum, persoana care dirijează traficul vă semnalizează să opriți, dar semaforul este verde. Pe care îl respectați?', '["Semaforul","Persoana care dirijează traficul","Niciunul, conduc cu grijă","Indicatorul rutier"]'::jsonb, 1, 'Semnalul persoanei care dirijează traficul are prioritate față de semafoare și indicatoare.', 'Persoana de la fața locului vede situația.', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r6', 'ro', 'Pe întuneric, cu faza scurtă, o persoană în haine închise pe marginea drumului este observată abia de la aproximativ…', '["300 m","150 m","50 m","10 m"]'::jsonb, 2, 'Cu faza scurtă, o persoană îmbrăcată în haine închise se distinge abia de la aproximativ 50 m; cu element reflectorizant sau vestă, de la aproximativ 150 m sau mai mult.', 'Mult mai aproape decât ați crede.', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r7', 'ro', 'Vă explodează o anvelopă pe un drum îngust, fără acostament. Ce faceți?', '["Mergeți încet până la un loc sigur sau chemați asistența rutieră, nu schimbați roata în trafic","Schimbați roata pe loc","Lăsați camionul și plecați pe jos","Faceți semn traficului să încetinească"]'::jsonb, 0, 'Schimbarea unei roți pe banda de circulație vă pune viața în pericol. Mergeți într-un loc sigur sau chemați ajutor și avertizați ceilalți participanți la trafic.', 'Întâi propria siguranță.', 'Tieliikennelaki 729/2018', null),
  ('tieturva', 'tieturva.r8', 'ro', 'Unde stați când trebuie să lucrați lângă vehicul, pe marginea drumului?', '["Pe partea vehiculului dinspre trafic","Pe partea opusă traficului, cu fața spre traficul care vine","În spatele vehiculului","Pe bandă, ca să vedeți mai bine"]'::jsonb, 1, 'Stați pe partea unde vehiculul vă protejează de trafic și astfel încât să vedeți traficul care vine și să vă puteți feri.', 'Lăsați vehiculul să vă protejeze.', 'Tieliikennelaki 729/2018', null),
  ('tyoturva', 'tyoturva.w1', 'ro', 'Un stivuitor circulă în zona de încărcare și trebuie să-i traversați traseul. Ce faceți?', '["Traversați repede","Așteptați ca stivuitorul să oprească singur","Faceți contact vizual cu stivuitoristul și asigurați-vă că vă vede","Treceți prin spatele stivuitorului"]'::jsonb, 2, 'Vizibilitatea stivuitoristului este limitată, mai ales cu sarcină. Intrați pe traseu doar când sunteți sigur că v-a văzut.', 'Faptul că vedeți pericolul nu înseamnă că sunteți văzut.', 'Työturvallisuuslaki 738/2002', null),
  ('tyoturva', 'tyoturva.w2', 'ro', 'Cum coborâți în siguranță din cabină?', '["Săriți jos","Cu fața spre vehicul, cu trei puncte de sprijin","Cu fața în afară, pe trepte","Ținându-vă de ușă"]'::jsonb, 1, 'Coborâți cu fața spre vehicul și păstrați mereu trei puncte de sprijin: două mâini și un picior sau două picioare și o mână. Săritul este o cauză frecventă de accidentări.', 'Ca pe o scară.', 'Työturvallisuuslaki 738/2002', null),
  ('tyoturva', 'tyoturva.w3', 'ro', 'O macara mută un container deasupra dumneavoastră. Ce este corect?', '["Pot trece pe dedesubt dacă ridicarea e lentă","Pot trece pe dedesubt dacă port cască","Pot trece pe dedesubt dacă macaragiul m-a văzut","Nu trec niciodată pe sub o sarcină suspendată"]'::jsonb, 3, 'Nu treceți niciodată pe sub o sarcină suspendată: un cablu, un dispozitiv de blocare sau containerul pot ceda. Casca nu protejează de un container care cade.', 'O cască nu rezistă la un container.', 'Työturvallisuuslaki 738/2002', null),
  ('tyoturva', 'tyoturva.w4', 'ro', 'Într-un port, un straddle carrier (portal pe roți) manipulează încărcătura dumneavoastră. Unde așteptați, dacă regulile portului nu prevăd altceva?', '["În cabină sau într-o zonă sigură marcată","Lângă camion, ca să văd tot","În spatele straddle carrier-ului","Pe containerul de deasupra"]'::jsonb, 0, 'În multe porturi șoferul așteaptă în cabină sau într-o zonă marcată, pentru că utilajele mari nu văd oamenii de pe sol. Respectați întotdeauna regulile proprii ale portului.', 'Utilajele mari nu văd oamenii de pe sol.', 'Työturvallisuuslaki 738/2002', null),
  ('tyoturva', 'tyoturva.w5', 'ro', 'O încărcătură aproape a căzut peste dumneavoastră, dar nimeni nu s-a rănit. Ce faceți?', '["Nimic, nu s-a întâmplat nimic","Le spuneți colegilor în pauză","Raportați incidentul evitat la limită angajatorului sau responsabilului locației","Faceți o poză pentru rețelele sociale"]'::jsonb, 2, 'Raportarea unui incident evitat la limită previne următorul accident. Raportați-l angajatorului și responsabilului locației.', 'Data viitoare cineva s-ar putea răni.', 'Työturvallisuuslaki 738/2002', null),
  ('tyoturva', 'tyoturva.w6', 'ro', 'Deschideți ușile din spate și bănuiți că încărcătura s-a deplasat. Ce faceți?', '["Deschid ușile repede și mă dau înapoi","Deschid cu grijă și stau lateral față de ușă, nu în față","Las încărcătorul să le deschidă","Împing ușile cu umărul în timp ce le deschid"]'::jsonb, 1, 'O încărcătură deplasată poate apăsa pe uși și poate cădea când se deschid. Deschideți încet și stați lateral, în afara zonei de cădere.', 'Unde ar ajunge încărcătura dacă ar cădea?', 'Työturvallisuuslaki 738/2002', null),
  ('tyoturva', 'tyoturva.w7', 'ro', 'Pe acoperișul semiremorcii s-a strâns zăpadă. Cum procedați?', '["Urc pe acoperiș pe la ușile din spate","Plec, zăpada va cădea singură","Rog un coleg să țină scara","Folosesc platforma locației, protecția împotriva căderii sau rampa de curățare a zăpezii"]'::jsonb, 3, 'O cădere de pe acoperișul semiremorcii înseamnă o accidentare gravă. Nu urcați pe acoperiș fără platformă sau protecție împotriva căderii; multe locații au o rampă de curățare a zăpezii. Zăpada care cade poate pune în pericol și alți participanți la trafic.', 'Acoperișul este înalt și alunecos.', 'Työturvallisuuslaki 738/2002', null),
  ('tyoturva', 'tyoturva.w8', 'ro', 'Cine răspunde de siguranță la un loc de încărcare când vă aflați la sediul altcuiva?', '["Angajatorul și operatorul locației, iar dumneavoastră trebuie să respectați și instrucțiunile","Doar propriul angajator","Doar operatorul locației","Nimeni, dacă sunteți acolo doar pentru scurt timp"]'::jsonb, 0, 'La un loc de muncă comun, responsabilitatea este împărțită: operatorul locației și angajatorii răspund de organizare, iar lucrătorul trebuie să respecte instrucțiunile primite.', 'Fiecare are partea sa.', 'Työturvallisuuslaki 738/2002', null)
